<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CLIFFORD — Personal intelligence</title>
<style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#020507;color:#e6f7fb}*{box-sizing:border-box}body{margin:0;min-height:100dvh;background:radial-gradient(ellipse at 50% 42%,#03141d 0,transparent 55%)}header{height:95px;margin:0 5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff0c}.brand{font-size:18px;font-weight:500;letter-spacing:.35em}.brand span{color:#52dff3}small,.eyebrow{font-size:10px;letter-spacing:.23em;text-transform:uppercase;color:#71858d}.status{display:flex;gap:9px;align-items:center;font-size:11px;color:#a3bac2}.dot{width:5px;height:5px;background:#65e4ed;border-radius:50%;box-shadow:0 0 12px #65e4ed}.workspace{position:relative;max-width:1100px;margin:auto;padding:54px 24px 28px;text-align:center}.eyebrow{color:#6c929e}h1{font-size:clamp(27px,4vw,44px);font-weight:300;letter-spacing:-.035em;margin:18px 0 8px}h1 em{font-style:normal;color:#8eebf6}p.subtitle{font-size:13px;color:#6d8790;line-height:1.8;margin:0}#visual{height:280px;position:relative;margin:20px -24px 0}canvas{display:block;width:100%;height:100%}.visual-caption{position:absolute;bottom:13px;width:100%;font-size:9px;letter-spacing:.3em;color:#507681;text-transform:uppercase}.panel{max-width:700px;margin:auto;text-align:left}.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.tag{font-size:9px;letter-spacing:.2em;color:#779aa6;text-transform:uppercase}button,select,input,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.35;cursor:default}.text-button{background:none;border:0;color:#83a8b5;font-size:11px;padding:8px}.text-button:hover{color:#c1f7fc}.composer{border:1px solid #214652;background:#071219b0;border-radius:14px;padding:9px 10px 9px 18px;display:flex;align-items:center;gap:10px;box-shadow:0 0 50px #0c6f8d0a}.composer:focus-within{border-color:#438fa0}textarea{resize:none;width:100%;height:42px;max-height:120px;padding:12px 0;background:none;border:0;outline:0;color:#d7edf2;font-size:13px}textarea::placeholder{color:#4f6a74}.send{width:38px;height:38px;flex-shrink:0;border-radius:10px;border:1px solid #4ca4b7;background:#123f4b;color:#b6f9ff;font-size:20px}.hint{display:flex;justify-content:space-between;font-size:10px;color:#49636d;padding:13px 3px}.transcript{margin:14px 0;max-height:240px;overflow:auto;scrollbar-width:thin}.message{white-space:pre-wrap;font-size:13px;line-height:1.85;color:#c2d9e0;padding:14px 0;border-bottom:1px solid #ffffff08}.message .label{display:block;font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:#4eb6c8;margin-bottom:6px}.message.user{color:#6f8e9b}.error{color:#efa99b;font-size:12px;line-height:1.7}footer{max-width:1000px;margin:32px auto 0;padding:24px;display:flex;justify-content:space-between;gap:20px;border-top:1px solid #ffffff08;color:#385560;font-size:9px;letter-spacing:.15em;text-transform:uppercase}a{color:#6e9eac;text-decoration:none}dialog{max-width:470px;width:calc(100% - 32px);background:#08141c;color:#d8edf3;border:1px solid #23434f;border-radius:18px;padding:28px;box-shadow:0 20px 120px #000}dialog::backdrop{background:#000a;backdrop-filter:blur(6px)}dialog h2{font-weight:400;margin-top:0;font-size:20px}dialog p{color:#6c909d;font-size:12px;line-height:1.8}dialog label{display:block;font-size:11px;color:#97b6c1;margin:20px 0 8px}dialog input{width:100%;background:#030b10;border:1px solid #284652;border-radius:8px;padding:12px;color:#ccebf4}dialog .actions{display:flex;justify-content:flex-end;gap:12px;margin-top:24px}.primary{border:1px solid #337b8e;background:#12404c;border-radius:8px;padding:10px 18px;color:#b7f5ff;font-size:12px}@media(max-width:600px){header{height:75px}.workspace{padding-top:40px}#visual{height:230px}.status{font-size:10px}footer{font-size:8px}.subtitle{padding:0 15px}}@media(prefers-reduced-motion:reduce){canvas{opacity:.7}}
</style>
</head>
<body>
<header><div class="brand"><span>◈</span> CLIFFORD</div><div class="status"><span class="dot"></span><span id="connection">Checking backend</span><form method="POST" action="{{ route('logout') }}">@csrf<button class="text-button" type="submit">Sign out ↗</button></form></div></header>
<main class="workspace"><div class="eyebrow">Your personal intelligence</div><h1>A little clarity. <em>Infinite possibility.</em></h1><p class="subtitle">A space to think, remember, and move things forward.</p>
<div id="visual" aria-hidden="true"><canvas id="wave"></canvas><div class="visual-caption" id="state">Ready when you are</div></div>
<section class="panel" aria-label="Conversation"><div class="toolbar"><span class="tag">Conversation</span><div><button class="text-button" id="voice">Enable voice</button><button class="text-button" id="stop" disabled>Stop</button><button class="text-button" id="new">New session +</button></div></div><div id="messages" class="transcript" role="log" aria-live="polite"></div><div id="error" class="error" role="alert"></div><form id="chat" class="composer"><textarea id="prompt" aria-label="Message Clifford" placeholder="What’s on your mind?" rows="1" maxlength="12000" required></textarea><button class="send" id="send" title="Send message" aria-label="Send message">↑</button></form><div class="hint"><span>Enter to send · Shift + Enter for a new line</span><span id="voiceStatus" role="status">Microphone off</span></div></section>
</main><footer><span>CLIFFORD / Private assistant</span><span>Gemma 3 12B · Hands-free voice <span style="color:#26505e">/</span> <a href="https://github.com/parsabe/Clifford/tree/documentation">API documentation ↗</a></span></footer>
<script type="module" src="/console/client.js"></script>
</body></html>
